INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(65384019, 'Alchemy Cycle', '炼金周期', 'アルケミー・サイクル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到发动回合的结束阶段时，自己场上表侧表示存在的怪兽全部的原本攻击力变成0。每次被这个效果把原本攻击力变成0的怪兽被战斗破坏送去墓地，从自己卡组抽1张卡。'),
(17573739, 'Alector, Sovereign of Birds', '神禽王 亚力克特', '神禽王アレクトール', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2400, 2000, '对方场上相同属性的怪兽表侧表示2只以上存在的场合，这张卡可以从手卡特殊召唤。1回合1次选择场上表侧表示存在的1张卡。选择的卡的效果在那个回合中无效。「神禽王 亚力克特」在场上只能有1张表侧表示存在。'),
(98787535, 'Aleirtt, the Ogdoadic Dark', '溟界之昏暗－乌濑特', '溟界の昏闇－アレート', 'Effect Monster', 'Reptile', 'DARK', 8, 2000, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，把自己场上1只怪兽解放才能发动。这张卡特殊召唤。那之后，对方可以从自身墓地选1只怪兽加入手卡。 ②：这张卡特殊召唤成功的场合，从除外的自己怪兽之中以包含爬虫类族怪兽的2只怪兽为对象才能发动。那些怪兽回到墓地。'),
(86120751, 'Aleister the Invoker', '召唤师 阿莱斯特', '召喚師アレイスター', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1000, 1800, '①：自己·对方回合，把这张卡从手卡送去墓地，以自己场上1只融合怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升1000。 ②：这张卡召唤·反转的场合才能发动。从卡组把1张「召唤魔术」加入手卡。'),
(97973962, 'Aleister the Invoker of Madness', '暴走召唤师 阿莱斯特', '暴走召喚師アレイスター', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1800, NULL, '种族和属性不同的怪兽2只 ①：这张卡的卡名只要在场上·墓地存在当作「召唤师 阿莱斯特」使用。 ②：这张卡已在怪兽区域存在的状态，融合怪兽融合召唤的场合才能发动。选自己1张手卡丢弃，从卡组把1张「召唤魔术」或者「法之圣典」加入手卡。 ③：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。从卡组把1张「魔法名-「大兽」」加入手卡。'),
(26372118, 'ALERT!', '警报！', 'ALERT！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把1只「救援ACE队」怪兽加入手卡。自己场上有「救援ACE队 消防栓」存在的场合，也能作为代替从卡组把1只「救援ACE队」怪兽加入手卡。'),
(43096270, 'Alexandrite Dragon', '紫翠玉龙', 'アレキサンドライドラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 4, 2000, 100, '拥有紫翠玉鳞的稀世珍龙。那美丽鳞片冠以古代帝王之名，被视为是神秘的象征。 ——它的获得者并未意识到已经抓住莫大的幸运。'),
(45154513, 'Alghoul Mazera', '巨食尸鬼 魔杰拉', 'アルグールマゼラ', 'Effect Monster', 'Zombie', 'EARTH', 8, 2800, 2300, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的不死族怪兽被战斗·效果破坏的场合，可以作为代替把手卡·墓地的这张卡除外。 ②：这张卡从手卡·墓地除外的场合才能发动。这张卡守备表示特殊召唤。那之后，可以让这张卡的等级下降1星。'),
(14504454, 'Alice, Lady of Lament', '恶之魔娘 爱丽斯', '悪魔嬢アリス', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1张陷阱卡除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤成功时，以自己墓地1只「恶魔娘」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：这张卡被解放的场合或者被对方破坏的场合才能发动。从卡组把「恶魔娘 爱莉丝」以外的1只攻击力·守备力的合计是2000的恶魔族怪兽加入手卡。'),
(47728740, 'Alich, Malebranche of the Burning Abyss', '彼岸恶鬼 亚利几诺', '彼岸の悪鬼 アリキーノ', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, NULL, '「彼岸的恶鬼 阿利基诺」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(652362, 'Alien Ammonite', '外星菊石', 'エーリアンモナイト', 'Tuner Monster', 'Reptile', 'LIGHT', 1, 500, 200, '①：这张卡召唤成功时，以自己墓地1只4星以下的「外星」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(17490535, 'Alien Brain', '外星人脑', 'エーリアン・ブレイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的爬虫类族怪兽被对方怪兽的攻击破坏送去墓地时才能发动。得到那个时候进行攻击的对方怪兽的控制权，那只怪兽当作爬虫类族使用。'),
(15475415, 'Alien Dog', '外星犬', 'エーリアン・ドッグ', 'Effect Monster', 'Reptile', 'LIGHT', 3, 1500, 1000, '自己对名字带有「外星」的怪兽的召唤成功时，这张卡可以从手卡特殊召唤。这个效果特殊召唤成功时，给对方场上表侧表示存在的怪兽放置2个A指示物。'),
(62437709, 'Alien Grey', '灰色外星人', 'エーリアン・グレイ', 'Flip Effect Monster', 'Reptile', 'LIGHT', 2, 300, 800, '反转：对方场上表侧表示存在的1只怪兽放置1个A指示物。放置有A指示物的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。此外，反转的这张卡被战斗破坏送去墓地时，从自己卡组抽1张卡。'),
(62315111, 'Alien Hunter', '外星人猎手', 'エーリアン・ハンター', 'Effect Monster', 'Reptile', 'WATER', 4, 1600, 800, '这张卡战斗破坏放置有A指示物的怪兽的场合，只有1次可以继续进行攻击。'),
(38468214, 'Alien Hypno', '催眠外星人', 'エーリアン・ヒュプノ', 'Gemini Monster', 'Reptile', 'WATER', 4, 1600, 700, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●选择放置有A指示物的对方场上1只怪兽得到控制权。每次自己的结束阶段时，得到控制权的怪兽的A指示物取除1个。得到控制权的怪兽的A指示物全部取除的场合，那只怪兽破坏。'),
(76573247, 'Alien Infiltrator', '外星人侵略者', 'エーリアン・ベーダー', 'Effect Monster', 'Reptile', 'EARTH', 2, 800, 500, '这张卡1回合只有1次，可以移动到没有使用的相邻的怪兽卡区域。这张卡的正对面没有对方的怪兽·魔法·陷阱卡存在的场合，这张卡可以直接攻击对方玩家。'),
(64160836, 'Alien Kid', '外星人小孩', 'エーリアン・キッズ', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1600, 700, '只要这张卡在自己场上表侧表示存在，每次对方场上有怪兽特殊召唤，给那个时候特殊召唤的怪兽放置1个A指示物。有A指示物放置的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。'),
(99532708, 'Alien Mars', '火星外星人', 'エーリアン・マーズ', 'Effect Monster', 'Reptile', 'FIRE', 3, 1000, 1000, '只要这张卡在场上表侧表示存在，「火星外星人」以外的放置有A指示物的怪兽的效果无效化。'),
(24104865, 'Alien Mother', '外星人母后', 'エーリアン・マザー', 'Effect Monster', 'Reptile', 'DARK', 6, 2300, 1500, '这张卡战斗破坏有A指示物放置的怪兽送去墓地的场合，那次战斗阶段结束时发动。破坏的那些怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在这张卡从场上离开的场合全部破坏。'),
(63253763, 'Alien Overlord', '外星人复仇者', 'エーリアン・リベンジャー', 'Effect Monster', 'Reptile', 'DARK', 6, 2200, 1600, '这张卡可以把场上存在的2个A指示物取除，从手卡特殊召唤。1回合1次，可以给对方场上表侧表示存在的全部怪兽放置1个A指示物。有A指示物放置的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。「外星人复仇者」在自己场上只能有1只表侧表示存在。'),
(58012107, 'Alien Psychic', '念力外星人', 'エーリアン・サイコ', 'Effect Monster', 'Reptile', 'DARK', 1, 200, 100, '这张卡召唤·反转召唤成功的场合变成守备表示。只要这张卡在场上表侧表示存在，放置有A指示物的怪兽不能攻击宣言。'),
(97127906, 'Alien Shocktrooper', '外星人士兵', 'エーリアン・ソルジャー', 'Normal Monster', 'Reptile', 'EARTH', 4, 1900, 800, '谜之生命体外星人的上级战士。虽拥有较高的攻击力，却没有掌握任何特殊能力。'),
(74974229, 'Alien Shocktrooper M-Frame', '外星人士兵 强力／外骨骼', 'エーリアン・ソルジャー M／フレーム', 'Link Monster', 'Reptile', 'LIGHT', NULL, 1900, NULL, '爬虫类族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只怪兽才能发动。丢弃的怪兽的原本等级数量的A指示物给场上的表侧表示怪兽放置。这个效果在对方回合也能发动。 ②：这张卡被战斗·效果破坏送去墓地的场合才能发动。从自己墓地选最多有着有A指示物放置的对方场上的怪兽数量的连接怪兽以外的爬虫类族怪兽特殊召唤（同名卡最多1张）。'),
(25920413, 'Alien Skull', '骷髅外星人', 'エーリアン・スカル', 'Effect Monster', 'Reptile', 'WIND', 4, 1600, 1800, '可以把对方场上1只3星以下的怪兽解放，这张卡从手卡往对方场上特殊召唤。这个方法特殊召唤的场合，这个回合自己不能通常召唤，特殊召唤时给这张卡放置1个A指示物。只要这张卡在场上表侧表示存在，有A指示物放置的怪兽和名字带有「外星」的怪兽进行战斗的场合，只在伤害计算时A指示物每有1个攻击力·守备力下降300。'),
(58066722, 'Alien Stealthbuster', '外星人破坏者', 'エーリアン・バスター', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1700, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。给那只怪兽放置2个A指示物。 ②：把墓地的这张卡除外，以有A指示物放置的1张卡为对象才能发动。那张卡破坏。这个效果在这张卡送去墓地的回合不能发动。'),
(91070115, 'Alien Telepath', '传心外星人', 'エーリアン・テレパス', 'Effect Monster', 'Reptile', 'FIRE', 4, 1600, 1000, '可以把对方怪兽放置的A指示物取除1个，场上1张魔法或者陷阱卡破坏。这个效果1回合只能使用1次。放置有A指示物的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。'),
(98719226, 'Alien Warrior', '外星人战士', 'エーリアン・ウォリアー', 'Effect Monster', 'Reptile', 'EARTH', 4, 1800, 1000, '这张卡被战斗破坏送去墓地时，破坏这张卡的怪兽放置2个A指示物。放置有A指示物的怪兽和名字带有「外星」的怪兽战斗的场合，每有1个A指示物攻击力·守备力下降300。'),
(70924884, 'Alinsection', '锯足锹形虫', 'インセクション', 'Normal Monster', 'Insect', 'EARTH', 3, 950, 700, '大甲虫。除了头上的锯子，手腕也变成了锯子。'),
(70335319, 'All-Eyes Phantom Dragon', '神眼幻龙', 'ゴッドアイズ・ファントム・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'LIGHT', 10, 3000, 2500, '这张卡不能通常召唤。「神眼幻龙」1回合1次在把包含龙族灵摆怪兽的自己场上2只以上的全部怪兽解放的场合才能从手卡·额外卡组特殊召唤。 ①：1回合1次，这张卡和对方怪兽进行战斗的伤害计算时发动。这张卡的攻击力直到回合结束时变成2倍。 ②：1回合1次，对方把魔法·陷阱卡的效果发动时，把自己场上1张魔法·陷阱卡送去墓地才能发动。那个发动无效。'),
(30834988, 'All-Out Attacks', '召唤限制-猛突的怪兽', '召喚制限－猛突するモンスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡在场上存在的场合怪兽特殊召唤成功时，那些怪兽变成表侧攻击表示。那个回合那些怪兽可以攻击的场合必须作出攻击。'),
(39138610, 'Allied Code Talker @Ignister', '合协码语者＠伊格尼斯者', 'アコード・トーカー＠イグニスター', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '效果怪兽3只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己墓地把攻击力2300的电子界族怪兽尽可能在作为这张卡所连接区的自己场上特殊召唤，这张卡的攻击力上升那个数量×500。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。 ②：对方把卡的效果发动时，把这张卡所连接区1只自己的连接怪兽解放才能发动。那个发动无效并除外。'),
(64428736, 'Alligator''s Sword', '飞龙战士', 'ワイバーンの戦士', 'Normal Monster', 'Beast', 'EARTH', 4, 1500, 1200, '剑技出色的蜥蜴人，音速般地挥舞着剑。'),
(3366982, 'Alligator''s Sword Dragon', '乘龙的飞龙', 'ドラゴンに乗るワイバーン', 'Fusion Monster', 'Dragon', 'WIND', 5, 1700, 1500, '「宝贝龙」＋「翼龙战士」 ①：对方场上的表侧表示怪兽只有地·水·炎属性怪兽的场合，这张卡可以直接攻击。'),
(68316358, 'Allure Dance', '魅惑之舞', '魅惑の舞', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「魅惑的女王」怪兽或1张「魅惑的宫殿」加入手卡。 ②：自己场上的「魅惑的女王」怪兽的攻击力上升自身的效果装备的怪兽的攻击力数值。 ③：把自己场上1张其他的魔法·陷阱卡送去墓地才能发动。从自己墓地把「魅惑的女王」怪兽尽可能特殊召唤（同名卡最多1张）。'),
(1475311, 'Allure of Darkness', '暗之诱惑', '闇の誘惑', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己抽2张。那之后，手卡有暗属性怪兽存在的场合，选那之内的1只除外。不存在的场合，自己手卡全部送去墓地。'),
(31322640, 'Allure Palace', '魅惑宫殿', '魅惑の宮殿', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合可以使用最多3次。 ①：自己场上的魔法师族怪兽的攻击力·守备力上升500。 ②：自己场上的「魅惑的女王」效果怪兽得到以下效果。 ●把用自身的效果把卡装备的这张卡送去墓地才能发动。从手卡·卡组把1只攻击力1500以下的魔法师族怪兽特殊召唤。 ③：把1张手卡送去墓地才能发动。从卡组选1只「魅惑的女王」怪兽加入手卡或在对方场上特殊召唤。'),
(87257460, 'Allure Queen LV3', '魅惑女王 LV3', '魅惑の女王 LV３', 'Effect Monster', 'Spellcaster', 'DARK', 3, 500, 500, '①：1回合1次，以对方场上1只3星以下的怪兽为对象才能发动。那只3星以下的对方怪兽当作装备魔法卡使用给这张卡装备（只有1只可以装备）。 ②：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。 ③：自己准备阶段，把用这张卡的效果把怪兽装备的这张卡送去墓地才能发动。从手卡·卡组把1只「魅惑的女王 LV5」特殊召唤。'),
(23756165, 'Allure Queen LV5', '魅惑女王 LV5', '魅惑の女王 LV５', 'Effect Monster', 'Spellcaster', 'DARK', 5, 1000, 1000, '①：这张卡是已用「魅惑的女王 LV3」的效果特殊召唤的场合，1回合1次，以对方场上1只5星以下的怪兽为对象才能发动。那只5星以下的对方怪兽当作装备魔法卡使用给这张卡装备（只有1只可以装备）。 ②：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。 ③：自己准备阶段，把用这张卡的效果把怪兽装备的这张卡送去墓地才能发动。从手卡·卡组把1只「魅惑的女王 LV7」特殊召唤。'),
(50140163, 'Allure Queen LV7', '魅惑女王 LV7', '魅惑の女王 LV７', 'Effect Monster', 'Spellcaster', 'DARK', 7, 1500, 1500, '①：这张卡是已用「魅惑的女王 LV5」的效果特殊召唤的场合，1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽当作装备魔法卡使用给这张卡装备（只有1只可以装备）。 ②：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。'),
(92881099, 'Alluring Mirror Split', '魅惑的千层镜', '魅惑の合わせ鏡', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「鹰身女郎」或者「鹰身女郎三姐妹」被战斗破坏时才能发动。原本卡名和那只怪兽不同的1只「鹰身」怪兽从卡组特殊召唤。 ②：场上的这张卡被对方的效果或者自己的「鹰身」卡的效果破坏的场合，以自己墓地1只「鹰身」怪兽为对象发动。那只怪兽特殊召唤。'),
(3544583, 'Allvain the Essence of Vanity', '无之毕竟 无果虚空', '無の畢竟 オールヴェイン', 'Fusion Monster', 'Fairy', 'DARK', 2, NULL, 2100, '通常怪兽×2'),
(40155554, 'Ally Mind', 'A・心灵', 'A・マインド', 'Normal Tuner Monster', 'Machine', 'DARK', 5, 1800, 1400, '为了强化正义盟军的思考回路而开发的高性能装置。嵌入从异虫星云飞来的陨石中取得的物质，以很高的调和能力著称。那未知力量的谜团至今仍未解开。'),
(26593852, 'Ally of Justice Catastor', 'A・O・J 灾难兽', 'A・O・J カタストル', 'Synchro Monster', 'Machine', 'DARK', 5, 2200, 1200, '调整＋调整以外的怪兽1只以上 ①：这张卡和暗属性以外的表侧表示怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。'),
(89386122, 'Ally of Justice Clausolas', '正义盟军 辉剑鸟', 'A・O・J クラウソラス', 'Normal Monster', 'Machine', 'DARK', 6, 2300, 1200, '霞之谷栖息的怪兽辉剑鸟为主题开发出的对外敌用战斗兵器。以从高空而来的奇袭玩弄敌人。'),
(36629203, 'Ally of Justice Core Destroyer', '正义盟军 核灭虫', 'A・O・J コアデストロイ', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 200, '这张卡和光属性怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。'),
(8822710, 'Ally of Justice Cosmic Gateway', '正义盟军 宇宙封闭机', 'A・O・J コズミック・クローザー', 'Effect Monster', 'Machine', 'DARK', 8, 2400, 1200, '对方场上包含光属性有怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。'),
(8233522, 'Ally of Justice Cycle Reader', 'A・O・J 循环读取者', 'A・O・J サイクルリーダー', 'Tuner Monster', 'Machine', 'DARK', 3, 1000, 1000, '把这张卡从手卡丢弃去墓地发动。选择对方墓地存在的最多2只光属性怪兽从游戏中除外。这个效果在对方回合也能发动。'),
(45586855, 'Ally of Justice Cyclone Creator', '正义盟军 造风鸟', 'A・O・J サイクロン・クリエイター', 'Tuner Monster', 'Machine', 'DARK', 3, 1400, 1200, '1回合1次，丢弃1张手卡才能发动。选场上的调整数量的场上的魔法·陷阱卡回到持有者手卡。'),
(9888196, 'Ally of Justice Decisive Armor', '正义盟军 决战兵器', 'A・O・J ディサイシブ・アームズ', 'Synchro Monster', 'Machine', 'DARK', 10, 3300, 3300, '调整＋调整以外的怪兽2只以上 对方场上有光属性怪兽表侧表示存在的场合，1回合1次，可以从下面效果选择1个发动。 ●把对方场上盖放的1张卡破坏。 ●把1张手卡送去墓地，对方场上存在的魔法·陷阱卡全部破坏。 ●把自己手卡全部送去墓地，把对方手卡确认并从那之中把光属性怪兽全部送去墓地。那之后给与对方基本分送去墓地的对方怪兽的攻击力合计数值的伤害。'),
(45033006, 'Ally of Justice Enemy Catcher', '正义盟军 擒敌乌贼', 'A・O・J エネミー・キャッチャー', 'Effect Monster', 'Machine', 'DARK', 6, 1800, 1800, '这张卡召唤成功时，直到这个回合的结束阶段时可以得到对方场上里侧守备表示存在的1只怪兽的控制权。'),
(69461394, 'Ally of Justice Field Marshal', '正义盟军 陆军元帅', 'A・O・J フィールド・マーシャル', 'Synchro Monster', 'Machine', 'DARK', 9, 2900, 2600, '调整＋调整以外的怪兽2只以上 这张卡不用同调召唤不能特殊召唤。这张卡的攻击破坏里侧守备表示怪兽送去墓地时，从卡组抽1张卡。'),
(25771826, 'Ally of Justice Garadholg', '正义盟军 雷剑兵', 'A・O・J ガラドホルグ', 'Effect Monster', 'Machine', 'DARK', 4, 1600, 400, '这张卡和光属性怪兽进行战斗的场合，伤害步骤内这张卡的攻击力上升200。'),
(19204398, 'Ally of Justice Light Gazer', '正义盟军 灯眼怪', 'A・O・J ライト・ゲイザー', 'Synchro Monster', 'Machine', 'DARK', 8, 2400, 1600, '调整＋调整以外的怪兽1只以上 这张卡的攻击力上升对方墓地存在的光属性怪兽数量×200的数值。'),
(76650663, 'Ally of Justice Nullfier', '正义盟军 遮光吸收兵', 'A・O・J ブラインド・サッカー', 'Effect Monster', 'Machine', 'DARK', 4, 1600, 1200, '和这张卡进行战斗的光属性怪兽的效果在伤害计算后无效化。'),
(45450218, 'Ally of Justice Omni-Weapon', '正义盟军 致命武器', 'A・O・J リーサル・ウェポン', 'Effect Monster', 'Machine', 'DARK', 5, 2200, 800, '这张卡战斗破坏光属性怪兽送去墓地时，从自己卡组抽1张卡。这个效果抽到的卡是4星以下的暗属性怪兽的场合，可以把那张卡给对方观看在自己场上特殊召唤。'),
(72845813, 'Ally of Justice Quarantine', '正义盟军 D.D.阻隔虫', 'A・O・J D.D.チェッカー', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 1200, '只要这张卡在场上表侧表示存在，双方不能把光属性怪兽特殊召唤。'),
(55982698, 'Ally of Justice Reverse Break', '正义盟军 破反车', 'A・O・J リバース・ブレイク', 'Effect Monster', 'Machine', 'DARK', 4, 1200, 1200, '场上表侧表示光属性怪兽存在的场合，这张卡破坏。这张卡向里侧守备表示怪兽攻击的场合，不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。'),
(52265835, 'Ally of Justice Rudra', '正义盟军 风哮怪', 'A・O・J ルドラ', 'Effect Monster', 'Machine', 'DARK', 5, 1900, 1200, '这张卡和光属性怪兽进行战斗的场合，伤害步骤内这张卡的攻击力上升700。'),
(3648368, 'Ally of Justice Searcher', '正义盟军 调查员', 'A・O・J リサーチャー', 'Effect Monster', 'Machine', 'DARK', 3, 1400, 100, '丢弃1张手卡发动。对方场上里侧守备表示存在的1只怪兽变成表侧攻击表示。这个时候，反转效果怪兽的效果不发动。这个效果1回合只能使用1次。'),
(85876417, 'Ally of Justice Thousand Arms', '正义盟军 千械鬼', 'A・O・J サウザンド・アームズ', 'Effect Monster', 'Machine', 'DARK', 4, 1700, NULL, '这张卡可以向对方场上表侧表示存在的光属性怪兽各作1次攻击。和光属性以外的怪兽进行战斗的场合，那次伤害计算前这张卡破坏。'),
(71438011, 'Ally of Justice Thunder Armor', '正义盟军 雷铠兵', 'A・O・J サンダー・アーマー', 'Effect Monster', 'Machine', 'DARK', 8, 2700, 2200, '这张卡不能特殊召唤。只要这张卡在自己场上表侧表示存在，自己场上存在的名字带有「正义盟军」的怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(22371016, 'Ally of Justice Unknown Crusher', '正义盟军 未知轰击象', 'A・O・J アンノウン・クラッシャー', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 800, '这张卡和光属性怪兽进行战斗时，把那只怪兽从游戏中除外。'),
(82377606, 'Ally of Justice Unlimiter', '正义盟军 无限虫', 'A・O・J アンリミッター', 'Effect Monster', 'Machine', 'DARK', 2, 600, 200, '把这张卡解放发动。自己场上表侧表示存在的1只名字带有「正义盟军」的怪兽的原本攻击力直到这个回合的结束阶段时变成2倍。'),
(59482302, 'Ally Salvo', '盟军·炸弹', 'A・ボム', 'Effect Monster', 'Machine', 'DARK', 2, 400, 300, '这张卡被和光属性怪兽的战斗破坏送去墓地时，选择场上2张卡破坏。'),
(92998610, 'Aloof Lupine', '孤高除兽', '孤高除獣', 'Effect Monster', 'Beast', 'DARK', 4, 1700, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤时，从手卡把1只怪兽除外才能发动。种族和除外的怪兽相同的1只怪兽从卡组除外。 ②：这张卡被战斗或者对方的效果破坏的场合，以自己的除外状态的1只怪兽为对象才能发动。那只怪兽加入手卡。'),
(77797992, 'Alpacaribou, Mystical Beast of the Forest', '森之圣兽 羊驼驯鹿', '森の聖獣 アルパカリブ', 'Effect Monster', 'Beast', 'EARTH', 7, 2700, 2100, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：自己场上表侧攻击表示存在的鸟兽族·昆虫族·植物族怪兽不会被战斗破坏。 ●守备表示：自己场上表侧守备表示存在的鸟兽族·昆虫族·植物族怪兽不会成为卡的效果的对象，不会被卡的效果破坏。'),
(73355951, 'Alpha Summon', '魔法名－“巴弗灭特”分解统合吧', '魔法名－「解体し統合せよ」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以除外的双方怪兽各1只为对象才能发动。作为对象的自己怪兽在对方场上特殊召唤，作为对象的对方怪兽在自己场上特殊召唤。'),
(42023223, 'Alpha The Electromagnet Warrior', '电磁石战士阿尔法', '電磁石の戦士α', 'Effect Monster', 'Rock', 'EARTH', 3, 1700, 1100, '「电磁石战士α」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只8星「磁石战士」怪兽加入手卡。 ②：对方回合把这张卡解放才能发动。从卡组把1只4星「磁石战士」怪兽特殊召唤。'),
(99785935, 'Alpha The Magnet Warrior', '磁石战士阿尔法', '磁石の戦士α', 'Normal Monster', 'Rock', 'EARTH', 4, 1400, 1700, '用α、β、γ来变形合体。'),
(73304257, 'Alpha, the Master of Beasts', '兽王 阿尔法', '獣王アルファ', 'Effect Monster', 'Beast', 'EARTH', 8, 3000, 2500, '这张卡不能通常召唤。对方场上的怪兽的攻击力合计比自己场上的怪兽的攻击力合计高的场合可以特殊召唤。这个卡名的效果1回合只能使用1次。 ①：以自己场上的兽族·兽战士族·鸟兽族怪兽任意数量为对象才能发动。那些怪兽回到手卡。那之后，选回到手卡的数量的对方场上的表侧表示怪兽回到手卡。这个效果的发动后，直到回合结束时自己的「兽王 阿尔法」不能直接攻击。'),
(10406322, 'Alsei, the Sylvan High Protector', '森罗的守神 森精', '森羅の守神 アルセイ', 'XYZ Monster', 'Plant', 'LIGHT', 8, 2300, 3200, '8星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，宣言1个卡名才能发动。自己卡组最上面的卡翻开，宣言的卡的场合，那张卡加入手卡。不是的场合，翻开的卡送去墓地。 ②：自己卡组的卡被效果送去墓地的场合，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡回到持有者卡组最上面或者最下面。'),
(21070956, 'Altar for Tribute', '牲祭的祭坛', '生贄の祭壇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只怪兽送去墓地。自己回复与此怪兽原本攻击力数值相同的基本分。'),
(61470213, 'Altergeist Adminia', '幻变骚灵・管理妮雅', 'オルターガイスト・アドミニア', 'Link Monster', 'Spellcaster', 'DARK', NULL, 3000, NULL, '「幻变骚灵」怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「幻变骚灵」陷阱卡在自己场上盖放。 ②：只在这张卡表侧表示存在才有1次，自己·对方的主要阶段，把自己场上1张卡送去墓地，以对方场上1只效果怪兽为对象才能发动。得到那只效果怪兽的控制权。那只怪兽也当作「幻变骚灵」怪兽使用。'),
(80143954, 'Altergeist Camouflage', '幻变骚灵・伪装', 'オルターガイスト・カモフラージュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「幻变骚灵」怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽不会被作为对方怪兽的攻击对象。（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击。） ②：装备怪兽为对象发动的对方怪兽的效果无效化。 ③：自己场上的「幻变骚灵」卡被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(21187631, 'Altergeist Dragvirion', '幻变骚灵・拖拽格巫琳', 'オルターガイスト・ドラッグウィリオン', 'Synchro Monster', 'Spellcaster', 'DARK', 6, 2200, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：特殊召唤的对方怪兽的攻击宣言时，让自己场上1只「幻变骚灵」怪兽回到持有者手卡才能发动。那次攻击无效。 ②：这张卡被解放送去墓地的场合才能发动。这张卡特殊召唤。'),
(86885905, 'Altergeist Emulatelf', '幻变骚灵・模拟精灵', 'オルターガイスト・エミュレルフ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（魔法师族·光·4星·攻1400/守1800）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：只要这张卡的效果特殊召唤的这张卡在怪兽区域存在，这张卡以外的自己场上的「幻变骚灵」陷阱卡不会成为效果的对象，不会被效果破坏。'),
(98753320, 'Altergeist Failover', '幻变骚灵・故障转移', 'オルターガイスト・フェイルオーバー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡以外的自己场上的卡被对方的效果破坏的场合才能发动。从手卡把1只「幻变骚灵」怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「幻变骚灵」怪兽为对象才能发动。那只怪兽加入手卡。'),
(12977245, 'Altergeist Fifinellag', '幻变骚灵・迟滞菲菲内拉', 'オルターガイスト・フィフィネラグ', 'Tuner Monster', 'Spellcaster', 'DARK', 2, NULL, 1000, '①：只要这张卡在怪兽区域存在，对方不能选择「幻变骚灵·延迟菲芬尼拉」以外的自己场上的「幻变骚灵」怪兽作为攻击对象，也不能作为效果的对象。'),
(85673903, 'Altergeist Fijialert', '幻变骚灵・警告菲溺尔', 'オルターガイスト・フィジアラート', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1400, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在，「幻变骚灵」连接怪兽在自己场上连接召唤时，以那只怪兽以外的场上1只连接怪兽为对象才能发动。这张卡在作为成为对象的怪兽所连接区的自己场上特殊召唤。这个回合，作为对象的怪兽也当作「幻变骚灵」怪兽使用。'),
(2547033, 'Altergeist Haunted Rock', '幻变骚灵・鬼影死锁', 'オルターガイスト・ホーンデッドロック', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。「幻变骚灵」卡的效果盖放的这张卡在盖放的回合也能发动。 ①：作为这张卡的发动时的效果处理，从手卡把1只「幻变骚灵」怪兽送去墓地。 ②：对方把陷阱卡发动时，从手卡把1只「幻变骚灵」怪兽送去墓地才能发动。那个效果无效并破坏。'),
(1508649, 'Altergeist Hexstia', '幻变骚灵・十六进赫斯提亚', 'オルターガイスト・ヘクスティア', 'Link Monster', 'Spellcaster', 'FIRE', NULL, 1500, NULL, '「幻变骚灵」怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的「幻变骚灵」怪兽的原本攻击力数值。 ②：魔法·陷阱卡的效果发动时，把这张卡所连接区1只「幻变骚灵」怪兽解放才能发动。那个发动无效并破坏。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「幻变骚灵」卡加入手卡。'),
(76685519, 'Altergeist Kidolga', '幻变骚灵・键盘侧录难近母', 'オルターガイスト・キードゥルガー', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1000, NULL, '「幻变骚灵」怪兽2只 ①：这张卡以外的自己的「幻变骚灵」怪兽给与对方战斗伤害时，以对方墓地1只怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。这个效果特殊召唤的怪兽不在这张卡攻击宣言过的回合不能攻击。 ②：这张卡被战斗破坏的场合，以自己墓地1张「幻变骚灵」卡为对象才能发动。那张卡加入手卡。'),
(52927340, 'Altergeist Kunquery', '幻变骚灵・问询坤蒂', 'オルターガイスト・クンティエリ', 'Effect Monster', 'Spellcaster', 'EARTH', 5, NULL, 2400, '①：自己场上有「幻变骚灵」卡存在的场合，对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤，那次攻击无效。 ②：这张卡特殊召唤成功的场合，以对方场上1张表侧表示的卡为对象才能发动。这只怪兽表侧表示存在期间，那张卡的效果无效化。'),
(27132400, 'Altergeist Malwisp', '幻变骚灵・恶意无线提供者', 'オルターガイスト・マルウィスプ', 'Tuner Monster', 'Spellcaster', 'LIGHT', 3, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以「幻变骚灵·恶意软件鬼火」以外的自己墓地1只「幻变骚灵」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的效果不能发动。'),
(35146019, 'Altergeist Manifestation', '幻变骚灵・物化', 'オルターガイスト・マテリアリゼーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己墓地1只「幻变骚灵」怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤，把这张卡当作装备卡使用给那只怪兽装备。这张卡离开场上时那只怪兽破坏。 ②：把墓地的这张卡除外，以自己墓地1张「幻变骚灵」陷阱卡为对象才能发动。那张卡加入手卡。'),
(53143898, 'Altergeist Marionetter', '幻变骚灵・网络傀儡师', 'オルターガイスト・マリオネッター', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1700, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。从卡组把1张「幻变骚灵」陷阱卡在自己场上盖放。 ②：以自己场上1张「幻变骚灵」卡和自己墓地1只「幻变骚灵」怪兽为对象才能发动。作为对象的场上的卡送去墓地，作为对象的墓地的怪兽特殊召唤。'),
(25533642, 'Altergeist Meluseek', '幻变骚灵・寻路美露莘', 'オルターガイスト・メリュシーク', 'Effect Monster', 'Spellcaster', 'WATER', 1, 500, 300, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时，以对方场上1张卡为对象才能发动。那张卡送去墓地。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「幻变骚灵·寻道梅露辛」以外的1只「幻变骚灵」怪兽加入手卡。'),
(23790299, 'Altergeist Memorygant', '幻变骚灵・内存摩莉甘特', 'オルターガイスト・メモリーガント', 'Link Monster', 'Spellcaster', 'DARK', NULL, 2800, NULL, '「幻变骚灵」怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：双方的战斗阶段，把自己场上1只其他怪兽解放才能发动。这张卡的攻击力上升那只怪兽的攻击力数值。 ②：这张卡战斗破坏怪兽时才能发动。选对方场上1只怪兽破坏。破坏的场合，这张卡只再1次可以继续攻击。 ③：这张卡被破坏的场合，可以作为代替把自己墓地1只怪兽除外。'),
(42790071, 'Altergeist Multifaker', '幻变骚灵・多重伪装者', 'オルターガイスト・マルチフェイカー', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1200, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己把陷阱卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动（这个效果发动的回合，自己不是「幻变骚灵」怪兽不能特殊召唤）。从卡组把「幻变骚灵·多功能诈骗者」以外的1只「幻变骚灵」怪兽守备表示特殊召唤。'),
(54126514, 'Altergeist Peritrator', '幻变骚灵・渗透佩莉', 'オルターガイスト・ペリネトレータ', 'Effect Monster', 'Spellcaster', 'FIRE', 1, 500, 300, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时才能发动。自己抽1张。 ③：这张卡从场上送去墓地的场合才能发动。从自己的手卡·卡组·场上（表侧表示）把「幻变骚灵·渗透佩里」以外的1张「幻变骚灵」卡送去墓地。'),
(57769391, 'Altergeist Pixiel', '幻变骚灵・像素妖精', 'オルターガイスト・ピクシール', 'Effect Monster', 'Spellcaster', 'WIND', 1, 100, 100, '这个卡名的效果1回合只能使用1次。 ①：把这张卡解放才能发动。从自己卡组上面把3张卡翻开，从那之中选1张「幻变骚灵」卡加入手卡，剩下的卡送去墓地。'),
(59185998, 'Altergeist Pookuery', '幻变骚灵・查询帕克', 'オルターガイスト・プークエリ', 'Effect Monster', 'Spellcaster', 'DARK', 1, 300, 100, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：把自己场上的「幻变骚灵」怪兽作为「幻变骚灵」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡在墓地存在，「幻变骚灵」连接怪兽在自己场上连接召唤的场合才能发动。这张卡加入手卡。'),
(93503294, 'Altergeist Primebanshee', '幻变骚灵・隐私元班西', 'オルターガイスト・プライムバンシー', 'Link Monster', 'Spellcaster', 'DARK', NULL, 2100, NULL, '「幻变骚灵」怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡以外的自己场上1只「幻变骚灵」怪兽解放才能发动。从卡组把1只「幻变骚灵」怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：这张卡从场上送去墓地的场合，以自己墓地1张「幻变骚灵」卡为对象才能发动。那张卡加入手卡。'),
(27541563, 'Altergeist Protocol', '幻变骚灵・协定', 'オルターガイスト・プロトコル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的「幻变骚灵」卡的效果的发动以及那些发动的效果不会被无效化。 ②：对方把怪兽的效果发动时，把这张卡以外的自己场上1张表侧表示的「幻变骚灵」卡送去墓地才能发动。那个发动无效并破坏。'),
(22024279, 'Altergeist Revitalization', '幻变骚灵・活化', 'オルターガイスト・リバイタリゼーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只「幻变骚灵」连接怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。进行1只「幻变骚灵」怪兽的召唤。'),
(89538537, 'Altergeist Silquitous', '幻变骚灵・泛在羽衣精', 'オルターガイスト・シルキタス', 'Effect Monster', 'Spellcaster', 'WIND', 2, 800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，让自己场上1张其他的「幻变骚灵」卡回到手卡，以对方场上1张卡为对象才能发动。那张卡回到手卡。 ②：这张卡从场上送去墓地的场合，以自己墓地1张「幻变骚灵」陷阱卡为对象才能发动。那张卡加入手卡。'),
(27632240, 'Altitude Knight', '虚空之骑士', '虚空の騎士', 'Effect Monster', 'Warrior', 'WIND', 4, 1400, 1200, '这张卡在场上表侧表示存在的场合场上的怪兽回到手卡·卡组时，从自己卡组把1只风属性怪兽送去墓地。这个效果1回合只能使用1次。'),
(62962630, 'Aluber the Jester of Despia', '惨绝戏之导化 阿卢绯尔', 'デスピアの導化アルベル', 'Effect Monster', 'Fairy', 'DARK', 4, 1800, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「烙印」魔法·陷阱卡加入手卡。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的融合怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合，以对方场上1只效果怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽的效果直到回合结束时无效。'),
(27024795, 'Alviss of the Nordic Alfar', '极星灵 阿尔维斯', '極星霊アルヴィース', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1000, '这个卡名的②的效果在决斗中只能使用1次。 ①：「极星」连接怪兽的效果只让这张卡被除外的场合才能发动。等级合计直到10的「极星」怪兽从自己场上1只，从卡组2只送去墓地。那之后，从额外卡组把1只「极神」怪兽特殊召唤。 ②：自己的「极神」怪兽因战斗以外的方法被对方送去墓地的场合，把墓地的这张卡除外才能发动。同名卡不在自己墓地的1只「极神」怪兽从额外卡组特殊召唤。'),
(2139640, 'Amabie', '阿玛比埃姑娘', 'あまびえさん', 'Effect Monster', 'Fairy', 'WATER', 3, NULL, NULL, '①：自己主要阶段1开始时，把手卡的这张卡给对方观看才能发动。双方玩家回复300基本分。'),
(32181268, 'Amano-Iwato', '天岩户', '天岩戸', 'Spirit Monster', 'Rock', 'EARTH', 4, 1900, 1200, '这张卡不能特殊召唤。 ①：只要这张卡在怪兽区域存在，双方不能把灵魂怪兽以外的怪兽的效果发动。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(43739056, 'Amanokujaki', '天孔邪鬼', '天孔邪鬼', 'Tuner Monster', 'Fiend', 'LIGHT', 3, 1000, 1000, '①：只要这张卡在怪兽区域存在，自己不能把这张卡以外的和这张卡相同属性的特殊召唤的怪兽的效果发动。 ②：1回合1次，自己·对方的主要阶段才能发动。这张卡的控制权移给对方。那之后，可以把这张卡的属性直到下个回合的结束时变更为任意属性。这个效果不在这张卡的原本持有者的回合不能发动。'),
(18988391, 'Amarylease', '解放朱顶红', 'アマリリース', 'Effect Monster', 'Plant', 'EARTH', 1, 100, 200, '自己的主要阶段时，把墓地的这张卡从游戏中除外才能发动。这个回合只有1次，自己把怪兽召唤的场合需要的解放可以减少1只。「解放朱顶红」的效果1回合只能发动1次。'),
(20073910, 'Amaterasu', '天照大神', '天照大神', 'Spirit Monster', 'Fairy', 'LIGHT', 9, 3000, 3000, '这张卡不能召唤·特殊召唤。 ①：里侧表示的这只怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡变成表侧守备表示才能发动。自己从卡组抽1张。 ②：这张卡反转的场合发动。这张卡以外的场上的卡全部除外。 ③：这张卡反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(662855, 'Amatsu-Okami of the Divine Peaks', NULL, NULL, 'Link Monster', 'Dragon', 'LIGHT', NULL, 3000, NULL, NULL),
(66984907, 'Amaze Attraction Cyclo-Coaster', '惊奇游乐设施·∀·旋风过山车', 'A・∀・CC', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：以对方场上1张魔法·陷阱卡为对象才能发动。那张卡和这张卡送去墓地。 ●对方：从卡组把1只「惊乐」怪兽加入手卡，这张卡送去墓地。'),
(92650018, 'Amaze Attraction Horror House', '惊奇游乐设施·∀·恐怖鬼屋', 'A・∀・HH', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ●对方：装备怪兽变成里侧守备表示。'),
(29867611, 'Amaze Attraction Majestic Merry-Go-Round', '惊奇游乐设施·∀·威风旋转木马', 'A・∀・MM', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：装备怪兽的控制者对应的以下效果适用。 ●自己：装备怪兽的攻击力上升500。装备怪兽被战斗·效果破坏的场合，可以作为代替把这张卡送去墓地。 ●对方：装备怪兽的攻击力下降给怪兽装备的自己的「游乐设施」陷阱卡数量×500。'),
(55262310, 'Amaze Attraction Rapid Racing', '惊奇游乐设施·∀·疾速赛车', 'A・∀・RR', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：以对方墓地1张卡为对象才能发动。装备怪兽的表示形式变更，作为对象的卡回到卡组。 ●对方：装备怪兽的等级直到回合结束时上升1星，表示形式变更。'),
(36591747, 'Amaze Attraction Thrill Train', '惊奇游乐设施·∀·惊险列车', 'A・∀・TT', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：装备怪兽的表示形式变更，自己墓地1张「游乐设施」陷阱卡由对方选出。那张卡在自己场上盖放。 ●对方：装备怪兽直到结束阶段除外。'),
(97182396, 'Amaze Attraction Viking Vortex', '惊奇游乐设施·∀·征服海盗船', 'A・∀・VV', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：1回合1次，对方怪兽的攻击宣言时才能发动。那次攻击无效，直到战斗阶段结束时装备怪兽的控制权变更。 ●对方：装备怪兽把效果发动时才能发动。装备怪兽回到持有者手卡。'),
(93473606, 'Amaze Attraction Wonder Wheel', '惊奇游乐设施·∀·神奇摩天轮', 'A・∀・WW', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：可以把装备怪兽的控制者对应的以下效果发动。 ●自己：双方的主要阶段才能发动。选1张手卡回到卡组最下面。那之后，自己从卡组抽1张。 ●对方：装备怪兽的攻击力·守备力直到回合结束时交换。'),
(31600845, 'Amazement Abomination Arlekino', '恐乐园的死配人 ＜A丑角＞', '恐楽園の死配人 ＜Arlechino＞', 'Effect Monster', 'Psychic', 'LIGHT', 7, 2600, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「惊乐」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从自己的卡组·墓地把1张「惊乐家族脸」加入手卡。 ②：对方回合，以场上1只其他的效果怪兽为对象才能发动。这张卡回到持有者卡组，从卡组把1只「惊乐园的支配人 ＜∀丑角＞」特殊召唤。那之后，作为对象的怪兽的攻击力变成0。'),
(94821366, 'Amazement Administrator Arlekino', '惊乐园的支配人 ＜∀丑角＞', '驚楽園の支配人 ＜∀rlechino＞', 'Effect Monster', 'Psychic', 'DARK', 7, 2600, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：陷阱卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：对方对怪兽的召唤·特殊召唤成功的场合，以那1只对方怪兽为对象才能发动。从卡组选1张「游乐设施」陷阱卡给那只对方怪兽装备。 ③：1回合1次，从自己墓地把「游乐设施」陷阱卡任意数量除外，以那个数量的对方场上的卡为对象才能发动。那些卡破坏。'),
(30829071, 'Amazement Ambassador Bufo', '惊乐园的大使 ＜B丑角＞', '驚楽園の大使 ＜Bufo＞', 'Effect Monster', 'Beast', 'EARTH', 3, 1600, 900, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1张「游乐设施」陷阱卡和对方场上1只怪兽为对象才能发动。那张墓地的卡给那只对方怪兽装备。 ②：以给怪兽装备的1张自己的「游乐设施」陷阱卡为对象才能发动。那张卡给1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽装备。这个效果在对方回合也能发动。'),
(22662014, 'Amazement Assistant Delia', '惊乐园的助手 ＜D丑角＞', '驚楽園の助手 ＜Delia＞', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1张「游乐设施」陷阱卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：从手卡以及自己场上的表侧表示的卡之中把1张「游乐设施」陷阱卡送去墓地才能发动。从卡组选1张「游乐设施」陷阱卡在自己的魔法与陷阱区域盖放。'),
(67314110, 'Amazement Attendant Comica', '惊乐园的案内人 ＜C丑角＞', '驚楽園の案内人 ＜Comica＞', 'Effect Monster', 'Machine', 'LIGHT', 4, 1400, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组选1张「游乐设施」陷阱卡在自己的魔法与陷阱区域盖放。 ②：以给怪兽装备的1张自己的「游乐设施」陷阱卡为对象才能发动。那张卡给1只自己场上的「惊乐」怪兽或者对方场上的表侧表示怪兽装备。这个效果在对方回合也能发动。'),
(20989253, 'Amazement Family Faces', '惊乐家族脸', 'アメイズメント・ファミリーフェイス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以有自己的「游乐设施」陷阱卡装备的对方场上1只怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：得到装备怪兽的控制权。 ③：装备怪兽只要在自己的怪兽区域存在，攻击力上升500，不能把效果发动，也当作「惊乐」怪兽使用。'),
(33773528, 'Amazement Precious Park', '惊乐珍宝园', 'アメイズメント・プレシャスパーク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己可以把1张「游乐设施」陷阱卡在盖放的回合的自己主要阶段发动。 ②：自己·对方的结束阶段，把给怪兽装备的自己场上1张「游乐设施」陷阱卡送去墓地，从自己墓地的卡以及除外的自己的卡之中以和送去墓地的卡卡名不同的1张「游乐设施」陷阱卡为对象才能发动。那张卡在自己的魔法与陷阱区域盖放。'),
(6374519, 'Amazement Special Show', '惊乐特别秀', 'アメイズメント・スペシャルショー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的「惊乐」怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，以那1只自己的「惊乐」怪兽为对象才能发动。那只怪兽回到持有者手卡。那之后，可以从手卡把1只「惊乐」怪兽特殊召唤。'),
(37803970, 'Amazing Pendulum', '惊异灵摆', 'アメイジング・ペンデュラム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「惊异灵摆」在1回合只能发动1张。 ①：自己的灵摆区域没有卡存在的场合才能发动。从自己的额外卡组把2只卡名不同的表侧表示的「魔术师」灵摆怪兽加入手卡。'),
(70389815, 'Amazing Time Ticket', '惊奇时段通行证', 'アメイジングタイムチケット', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付800基本分才能发动。发动回合的以下效果适用。 ●自己回合：从卡组把1张「惊乐」卡加入手卡。 ●对方回合：从卡组选1张「游乐设施」陷阱卡在自己的魔法与陷阱区域盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(17968114, 'Amazon of the Seas', '海原的女战士', '海原の女戦士', 'Normal Monster', 'Fish', 'WATER', 4, 1300, 1400, '侍奉海神的美丽人鱼战士，守护着神圣的区域。'),
(91869203, 'Amazoness Archer', '亚马逊射手', 'アマゾネスの射手', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, 1000, '①：把自己场上2只怪兽解放才能发动。给与对方1200伤害。'),
(67987611, 'Amazoness Archers', '亚马逊弩弓队', 'アマゾネスの弩弓隊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '只有在对方进行攻击宣言，且自己场上存在名称中含有「亚马逊」字样的怪兽时这张卡才能发动。将对方场上所有怪兽都变成表向攻击表示（此时反转不发动），攻击力下降500点。对方所有的怪兽都必须进行攻击。'),
(23965033, 'Amazoness Augusta', '亚马逊女帝王', 'アマゾネス女帝王', 'Fusion Monster', 'Warrior', 'EARTH', 10, 3200, 2800, '「亚马逊」融合怪兽＋「亚马逊」怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合才能发动。从卡组把1只「亚马逊」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡以外的自己场上的「亚马逊」卡不会成为对方的效果的对象，不会被对方的效果破坏。 ③：「亚马逊女帝」或者「亚马逊女王」为素材作融合召唤的这张卡在同1次的战斗阶段中可以作2次攻击。'),
(10928224, 'Amazoness Baby Tiger', '亚马逊宠物仔虎', 'アマゾネスペット仔虎', 'Effect Monster', 'Beast', 'EARTH', 2, 500, 500, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「亚马逊宠物虎」使用。 ②：这张卡在手卡·墓地存在，自己场上有「亚马逊」怪兽召唤·特殊召唤的场合才能发动。这张卡特殊召唤。 ③：这张卡的攻击力上升自己墓地的「亚马逊」卡数量×100。'),
(73574678, 'Amazoness Blowpiper', '亚马逊吹箭兵', 'アマゾネスの吹き矢兵', 'Effect Monster', 'Warrior', 'EARTH', 3, 800, 1500, '在自己的每1个准备阶段选择对方场上1只怪兽。被选择的怪兽攻击力下降500直到回合结束。'),
(57312333, 'Amazoness Call', '亚马逊的叫声', 'アマゾネスの叫声', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选「亚马逊的叫声」以外的1张「亚马逊」卡加入手卡或送去墓地。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「亚马逊」怪兽为对象才能发动。这个回合，那只怪兽以外的自己怪兽不能攻击，作为对象的怪兽可以向对方怪兽全部各作1次攻击。'),
(29654737, 'Amazoness Chain Master', '亚马逊锁链使', 'アマゾネスの鎖使い', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1300, '①：这张卡被战斗破坏送去墓地时，支付1500基本分才能发动。把对方手卡确认，从那之中选1只怪兽加入自己手卡。'),
(4591250, 'Amazoness Empress', '亚马逊女帝', 'アマゾネス女帝', 'Fusion Monster', 'Warrior', 'EARTH', 8, 2800, 2400, '「亚马逊女王」＋「亚马逊」怪兽 ①：只要这张卡在怪兽区域存在，这张卡以外的自己场上的「亚马逊」卡不会被战斗·效果破坏。 ②：自己的「亚马逊」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：融合召唤的表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。从自己的手卡·卡组·墓地选1只「亚马逊女王」特殊召唤。'),
(55821894, 'Amazoness Fighter', '亚马逊格斗战士', 'アマゾネスの格闘戦士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1300, '这张卡进行战斗时，这张卡的控制者所受的战斗伤害为零。'),
(36100154, 'Amazoness Fighting Spirit', '亚马逊的斗志', 'アマゾネスの闘志', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '名字带有「亚马逊」的怪兽向持有比那个攻击力高的攻击力的怪兽攻击的场合，只在伤害计算时攻击怪兽的攻击力上升1000。'),
(97692972, 'Amazoness Golden Whip Master', '亚马逊金鞭使', 'アマゾネスの金鞭使い', 'Pendulum Effect Monster', 'Warrior', 'EARTH', 5, 2000, 1200, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。 ②：这张卡在墓地存在的状态，自己场上有「亚马逊」怪兽特殊召唤的场合才能发动。这张卡在自己的灵摆区域放置。'),
(25396150, 'Amazoness Hall', '亚马逊拜谒间', 'アマゾネス拝謁の間', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从自己墓地的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选1只「亚马逊」怪兽加入手卡或选1只「亚马逊」灵摆怪兽在自己的灵摆区域放置。 ②：自己场上有「亚马逊」怪兽卡存在，对方场上有怪兽特殊召唤的场合，以那1只对方怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力的数值。'),
(79965360, 'Amazoness Heirloom', '亚马逊的秘宝', 'アマゾネスの秘宝', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「亚马逊」的怪兽才能装备。装备怪兽1回合只有1次不会被战斗破坏。装备怪兽攻击的场合，受到那次攻击的怪兽在伤害计算后破坏。'),
(62480168, 'Amazoness Hot Spring', '亚马逊的秘汤', 'アマゾネスの秘湯', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「亚马逊」怪兽加入手卡或选1只「亚马逊」灵摆怪兽在自己的灵摆区域放置。 ②：自己场上有「亚马逊」怪兽卡存在，自己受到战斗伤害时才能发动。自己基本分回复受到的伤害的数值。'),
(83407038, 'Amazoness Onslaught', '亚马逊的急袭', 'アマゾネスの急襲', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己·对方的战斗阶段才能发动。从手卡把1只「亚马逊」怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力直到回合结束时上升500。 ②：自己的「亚马逊」怪兽和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽除外。 ③：场上的这张卡被破坏送去墓地的场合，以自己墓地1只「亚马逊」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(47480070, 'Amazoness Paladin', '亚马逊圣战士', 'アマゾネスの聖戦士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 300, '自己场上每存在1张名称中含有「亚马逊」的怪兽卡，这张卡的攻击力上升100点。'),
(68507541, 'Amazoness Pet Liger', '亚马逊宠物虎狮子', 'アマゾネスペット虎獅子', 'Fusion Monster', 'Beast', 'EARTH', 7, 2500, 2400, '「亚马逊宠物虎」＋「亚马逊」怪兽 ①：这张卡攻击的伤害计算时才能发动。这张卡的攻击力只在那次伤害计算时上升500。 ②：自己的「亚马逊」怪兽向对方怪兽攻击的伤害计算后，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降800。 ③：只要这张卡在怪兽区域存在，对方怪兽不能向这张卡以外的「亚马逊」怪兽攻击。'),
(59353647, 'Amazoness Pet Liger King', '亚马逊宠物虎狮王', 'アマゾネスペット虎獅王', 'Fusion Monster', 'Beast', 'EARTH', 9, 2900, 2800, '5星以上的「亚马逊」怪兽＋「亚马逊」怪兽 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方怪兽不能向这张卡以外的怪兽攻击。 ②：以自己场上1张「亚马逊」卡和自己墓地1只战士族「亚马逊」怪兽为对象才能发动。作为对象的场上的卡破坏，作为对象的墓地的怪兽特殊召唤。这个效果发动的回合，这张卡不能攻击。'),
(84539520, 'Amazoness Princess', '亚马逊王女', 'アマゾネス王女', 'Effect Monster', 'Warrior', 'EARTH', 3, 1200, 900, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「亚马逊女王」使用。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「亚马逊」魔法·陷阱卡加入手卡。 ③：这张卡的攻击宣言时，把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。从卡组把「亚马逊王女」以外的1只「亚马逊」怪兽守备表示特殊召唤。'),
(15951532, 'Amazoness Queen', '亚马逊女王', 'アマゾネス女王', 'Effect Monster', 'Warrior', 'EARTH', 6, 2400, 1800, '①：只要这张卡在怪兽区域存在，自己的「亚马逊」怪兽不会被战斗破坏。'),
(53162898, 'Amazoness Sage', '亚马逊贤者', 'アマゾネスの賢者', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, 700, '这张卡攻击的场合，那次伤害步骤结束时选择对方场上存在的1张魔法·陷阱卡破坏。'),
(71209500, 'Amazoness Scouts', '亚马逊童军', 'アマゾネス・スカウト', 'Effect Monster', 'Warrior', 'EARTH', 2, 500, 1100, '把这张卡解放发动。自己场上表侧表示存在的名字带有「亚马逊」的怪兽在这个回合不会成为效果怪兽的效果的对象，不会被魔法·陷阱·效果怪兽的效果破坏。这个效果在对方回合也能发动。'),
(86758746, 'Amazoness Secret Arts', '亚马逊的秘术', 'アマゾネスの秘術', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·场上把「亚马逊」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。这个回合，自己把「亚马逊」融合怪兽融合召唤的场合只有1次，也能把自己的额外卡组1只「亚马逊」怪兽送去墓地作为融合素材。'),
(6459419, 'Amazoness Shamanism', '亚马逊转生术', 'アマゾネス転生術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「亚马逊」的怪兽全部破坏。那之后，可以把最多和破坏数量相同数量的自己墓地存在的4星以下的名字带有「亚马逊」的怪兽表侧守备表示特殊召唤。'),
(24087580, 'Amazoness Silver Sword Master', '亚马逊银剑使', 'アマゾネスの銀剣使い', 'Pendulum Effect Monster', 'Warrior', 'EARTH', 3, 1200, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。 ②：这张卡在墓地存在的状态，自己场上有「亚马逊」怪兽特殊召唤的场合才能发动。这张卡在自己的灵摆区域放置。'),
(81325903, 'Amazoness Spellcaster', '亚马逊诅咒师', 'アマゾネスの呪詛師', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '到回合终了时为止，自己场上1只表侧表示的名称中含有「亚马逊」字样的怪兽与对方场上1只表侧表示的怪兽的原本攻击力相互交换。'),
(97870394, 'Amazoness Spiritualist', '亚马逊灵术师', 'アマゾネス霊術師', 'Effect Monster', 'Warrior', 'EARTH', 2, 800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以「亚马逊灵术师」以外的自己场上1张「亚马逊」卡为对象才能发动。那张卡回到持有者手卡，这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「亚马逊」怪兽不能从额外卡组特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1张「融合」加入手卡。'),
(31102447, 'Amazoness Spy', '亚马逊斥候', 'アマゾネスの斥候', 'Effect Monster', 'Warrior', 'EARTH', 3, 800, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡以外的手卡1只「亚马逊」怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡被战斗破坏送去墓地时，以「亚马逊斥候」以外的自己墓地1只「亚马逊」怪兽为对象才能发动。那只怪兽加入手卡或回到卡组。'),
(94004268, 'Amazoness Swords Woman', '亚马逊剑士', 'アマゾネスの剣士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1600, '①：这张卡的战斗发生的对自己的战斗伤害由对方代受。'),
(10979723, 'Amazoness Tiger', '亚马逊宠物虎', 'アマゾネスペット虎', 'Effect Monster', 'Beast', 'EARTH', 4, 1100, 1500, '①：「亚马逊宠物虎」在自己场上只能有1只表侧表示存在。 ②：这张卡的攻击力上升自己场上的「亚马逊」怪兽数量×400。 ③：只要这张卡在怪兽区域存在，对方怪兽不能向这张卡以外的「亚马逊」怪兽攻击。'),
(89567993, 'Amazoness Trainee', '亚马逊训练生', 'アマゾネス訓練生', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1300, '这张卡战斗破坏的怪兽不送去墓地回到持有者卡组最下面。这张卡战斗破坏对方怪兽的场合，这张卡的攻击力上升200。'),
(712559, 'Amazoness Village', '亚马逊之里', 'アマゾネスの里', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「亚马逊」怪兽的攻击力上升200。 ②：1回合1次，「亚马逊」怪兽被战斗·效果破坏送去墓地时才能发动。自己把持有那只「亚马逊」怪兽的原本等级以下的等级的1只「亚马逊」怪兽从卡组特殊召唤。'),
(50486289, 'Amazoness War Chief', '亚马逊战士长', 'アマゾネスの戦士長', 'Effect Monster', 'Warrior', 'EARTH', 5, 1900, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「亚马逊」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选1张「亚马逊」魔法·陷阱卡或者「融合」在自己场上盖放。这个回合，自己不用「亚马逊」怪兽不能攻击。'),
(22082163, 'Amazoness Willpower', '亚马逊的意志', 'アマゾネスの意地', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从自己墓地选择1只名字带有「亚马逊」的怪兽，攻击表示特殊召唤。这个效果特殊召唤的怪兽不能把表示形式变更，可以攻击的场合必须作出攻击。这张卡不在场上存在时，那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(41224658, 'Ambitious Gofer', '野望之高弗', '野望のゴーファー', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, 100, '1回合1次，选择对方场上存在的最多2只怪兽才能发动。对方可以把手卡1只怪兽给人观看让这张卡的效果无效。不给观看的场合，选择的怪兽破坏。'),
(98927491, 'Ambulance Rescueroid', '救援型急救机人', 'レスキューキューロイド', 'Fusion Monster', 'Machine', 'FIRE', 6, 2300, 1800, '「救援机人」＋「急救机人」 这只怪兽不能作融合召唤以外的特殊召唤。自己场上存在的怪兽被战斗破坏送去墓地时，可以使那只怪兽守备表示特殊召唤。这个效果1回合只能使用1次。'),
(36378213, 'Ambulanceroid', '急救机人', 'キューキューロイド', 'Effect Monster', 'Machine', 'EARTH', 3, 300, 1200, '名字带有「机人」的怪兽从自己墓地加入手卡时，可以特殊召唤那只怪兽。'),
(77972406, 'Ambush Fangs', '反击的毒牙', '反撃の毒牙', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「蛇毒」的怪兽受到攻击宣言时才能发动。把1只对方怪兽的攻击无效，战斗阶段结束。那之后，给攻击怪兽放置1个毒指示物。'),
(13332685, 'Ame no Habakiri no Mitsurugi', '天羽羽斩之巳剑', '天羽々斬之巳剣', 'Ritual Effect Monster', 'Reptile', 'DARK', 8, 2400, 1800, '「巳剑降临」降临 这个卡名的①的效果在决斗中只能使用1次，③的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从卡组把1只「巳剑」怪兽特殊召唤。那之后，自己场上1只怪兽解放。 ②：对方场上的怪兽的攻击力下降800。 ③：这张卡被解放的场合才能发动。从卡组把「天羽羽斩之巳剑」以外的1张「巳剑」卡加入手卡。那之后，可以把这张卡特殊召唤。'),
(19899073, 'Ame no Murakumo no Mitsurugi', '天丛云之巳剑', '天叢雲之巳剣', 'Ritual Effect Monster', 'Reptile', 'DARK', 8, 3200, 800, '「巳剑降临」降临 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。对方场上的怪兽全部破坏。 ②：对方把效果发动时才能发动。对方可以选1张手卡丢弃。没丢弃的场合，那个效果无效化。 ③：这张卡被解放的场合才能发动。从卡组把「天丛云之巳剑」以外的1张「巳剑」卡加入手卡。那之后，可以把这张卡特殊召唤。'),
(95174353, 'Ameba', '阿米巴', 'アメーバ', 'Effect Monster', 'Aqua', 'WATER', 1, 300, 350, '场上表侧表示存在的这张卡的控制权转移给对方时，对方受到2000分的伤害。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(40213117, 'Amores of Prophecy', '魔导弓士 拉穆尔', '魔導弓士 ラムール', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 600, 2000, '1回合1次，把手卡1张名字带有「魔导书」的魔法卡给对方观看才能发动。从手卡把1只4星以下的魔法师族怪兽特殊召唤。'),
(98287529, 'Amorphactor Pain, the Imagination Dracoverlord', '虚龙魔王 无形矢·心灵', '虚竜魔王アモルファクターP', 'Ritual Effect Monster', 'Dragon', 'EARTH', 8, 2950, 2500, '「无形阵·假面」降临。 ①：这张卡仪式召唤成功的场合，下次的对方回合的主要阶段1跳过。 ②：只要这张卡在怪兽区域存在，场上的表侧表示的融合·同调·超量怪兽的效果无效化。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「虚龙魔王 无形矢·心灵」以外的1只「龙魔王」怪兽加入手卡。'),
(33300669, 'Amorphage Envy', '无形噬体·忧郁', 'アモルファージ・キャヴム', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 4, NULL, 2050, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(34522216, 'Amorphage Gluttony', '无形噬体·暴食', 'アモルファージ・ガストル', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 2, NULL, 1850, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(69072185, 'Amorphage Goliath', '无形噬体·虚饰', 'アモルファージ・イリテュム', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 8, 2750, NULL, '①：只要这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(7305060, 'Amorphage Greed', '无形噬体·强欲', 'アモルファージ・プレスト', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 4, NULL, 1950, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(50554729, 'Amorphage Infection', '无形噬体感染', 'アモルファージ・インフェクション', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「无形噬体感染」的②的效果1回合只能使用1次。 ①：场上的「无形噬体」怪兽的攻击力·守备力上升场上的「无形噬体」卡数量×100。 ②：自己的手卡·场上的怪兽被解放的场合或者被战斗·效果破坏的场合才能发动。从卡组把1张「无形噬体」卡加入手卡。'),
(70917315, 'Amorphage Lechery', '无形噬体·色欲', 'アモルファージ・ルクス', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 2, 1350, NULL, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(47598941, 'Amorphage Lysis', '无形噬体溶解', 'アモルファージ・ライシス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「无形噬体溶解」的②的效果1回合只能使用1次。 ①：「无形噬体」怪兽以外的场上的怪兽的攻击力·守备力下降场上的「无形噬体」卡数量×100。 ②：自己的灵摆区域的卡被破坏的场合才能发动。从卡组选1只「无形噬体」灵摆怪兽在自己的灵摆区域放置。'),
(6283472, 'Amorphage Pride', '无形噬体·傲慢', 'アモルファージ・ヒュペル', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 4, 1750, NULL, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(32687071, 'Amorphage Sloth', '无形噬体·怠惰', 'アモルファージ・ノーテス', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 6, 2250, NULL, '①：只要这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(79794767, 'Amorphage Wrath', '无形噬体·愤怒', 'アモルファージ・オルガ', 'Pendulum Effect Monster', 'Dragon', 'EARTH', 4, 1650, NULL, '①：只要灵摆召唤·反转过的这张卡在怪兽区域存在，双方不是「无形噬体」怪兽不能从额外卡组特殊召唤。'),
(23160024, 'Amorphous Persona', '无形阵·假面', 'アモルファスP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「无形噬体」怪兽的攻击力·守备力上升300。 ②：只要这张卡在场地区域存在，每次自己场上的「无形噬体」怪兽被解放让自己从卡组抽1张。这个效果1回合可以适用最多2次。 ③：把墓地的这张卡除外才能发动。从自己的手卡·场上把等级合计直到8的灵摆怪兽解放，从手卡把「虚龙魔王 无形矢·心灵」仪式召唤。'),
(67371383, 'Amphibian Beast', '半鱼兽', '半魚獣・フィッシャービースト', 'Normal Monster', 'Fish', 'WATER', 6, 2400, 2000, '在陆地像兽一样，在海里像鱼一样都能快速攻击。'),
(40173854, 'Amphibious Bugroth', '水陆两用战斗艇', '水陸両用バグロス', 'Fusion Monster', 'Aqua', 'WATER', 5, 1850, 1300, '「陆战型战斗艇」＋「守卫海洋的战士」'),
(4754691, 'Amphibious Bugroth MK-11', '水陆两用战斗艇 Mk-11', '水陸両用バグロス Mk－１１', 'Effect Monster', 'Machine', 'WATER', 5, 1850, 1500, '这个卡名的②的效果1回合只能使用1次。 ①：场上没有「海」存在的场合，这张卡的攻击力上升700，这张卡不能直接攻击。 ②：场上有「海」存在的场合，以水属性以外的1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(64342551, 'Amphibious Bugroth MK-3', '水陆两用战斗艇 Mk-3', '水陸両用バグロス Mk－３', 'Effect Monster', 'Machine', 'WATER', 4, 1500, 1300, '当场上存在「海」时，这张卡可以对对方进行直接攻击。'),
(20665527, 'Amphibious Swarmship Amblowhale', '扬陆群舰 陆地巡洋鲸', '揚陸群艦アンブロエール', 'Link Monster', 'Machine', 'FIRE', NULL, 2600, NULL, '效果怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升双方墓地的连接怪兽数量×200。 ②：这张卡被破坏的场合，以自己或对方的墓地1只连接3以下的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ③：这张卡在墓地存在的状态，场上的连接3以下的怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。场上1张卡破坏。'),
(303660, 'Amplifier', '电脑增幅器', '電脳増幅器', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「人造人-念力震慑者」才能装备。这张卡的发动和效果不会被无效化。 ①：装备怪兽持有的「双方不能把场上的陷阱卡的效果发动，场上的陷阱卡的效果无效化」效果作为「对方不能把场上的陷阱卡的效果发动，对方场上的陷阱卡的效果无效化」适用。 ②：这张卡从场上离开时装备怪兽破坏。'),
(75380687, 'Amulet Dragon', '咒符龙', '呪符竜', 'Fusion Monster', 'Dragon', 'DARK', 8, 2900, 2500, '「黑魔术师」＋龙族怪兽 这张卡用以上记的卡为融合素材的融合召唤以及用「蒂迈欧之眼」的效果才能特殊召唤。 ①：这张卡特殊召唤的场合，以自己·对方的墓地的魔法卡任意数量为对象发动。那些卡除外，这张卡的攻击力上升除外的卡数量×100。 ②：这张卡被破坏的场合，以自己墓地1只魔法师族怪兽为对象才能发动。那只魔法师族怪兽特殊召唤。'),
(5183693, 'Amulet of Ambition', '下克上的首饰', '下克上の首飾り', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '通常怪兽才能装备。和比装备怪兽等级高的怪兽进行战斗的场合，装备怪兽的攻击力只在伤害计算时上升等级差×500的数值。这张卡被送去墓地时，这张卡可以回到卡组最上面。'),
(61160289, 'Amunessia, the Ogdoadic Queen', '溟界妃－阿湄内西娅', '溟界妃－アミュネシア', 'Effect Monster', 'Reptile', 'DARK', 8, 2700, 2100, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，把自己场上2只怪兽解放才能发动。这张卡特殊召唤。 ②：从对方墓地有怪兽特殊召唤的场合才能发动。选对方场上1张卡送去墓地。 ③：从对方的手卡·卡组有怪兽被送去墓地的场合才能发动。从自己墓地选「溟界妃-阿蒙涅西娅」以外的1只光·暗属性的爬虫类族怪兽特殊召唤。'),
(23927567, 'An Owl of Luck', '告知幸运的白鸮', '幸運を告げるフクロウ', 'Flip Effect Monster', 'Winged Beast', 'WIND', 2, 300, 500, '反转：从卡组中选择1张场地魔法卡，放在自己卡组最上面。当「王家长眠之谷」在场上存在时，可以将选择的场地魔法卡加入手卡。'),
(19763315, 'An Unfortunate Report', '不运的报告', '不運なリポート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方下次的战斗阶段进行2次。'),
(80570228, 'Anarchist Monk of the Six Samurai', '六武众之破戒僧', '六武衆の破戒僧', 'Tuner Monster', 'Warrior', 'DARK', 3, 500, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：自己场上有「六武众的破戒僧」以外的「六武众」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1张「六武众」速攻魔法卡加入手卡。 ③：这张卡为素材作同调召唤的「六武众」怪兽得到以下效果。 ●对方场上的怪兽的等级下降1星。'),
(58324930, 'Anarchist Monk Ranshin', '破戒僧 鸾亲', '破戒僧 ランシン', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1800, 100, '这张卡被对方从场上送去墓地时，选择对方墓地存在的1只怪兽从游戏中除外。'),
(52296675, 'Anchamoufrite', '潜伏修道士', 'アンカモフライト', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 5, 1800, NULL, '这张卡不能通常召唤。这张卡在额外卡组表侧表示存在，「迷彩光书签」以外的卡不在自己的额外卡组存在的场合才能特殊召唤。这个方法的「迷彩光书签」的特殊召唤1回合只能有1次。 ①：怪兽区域的表侧表示的这张卡从场上离开的场合除外。'),
(54656950, 'Anchorbolt Hedgehog', '锚栓螺丝刺猬', 'アンカーボルト・ヘッジホッグ', 'Effect Monster', 'Machine', 'EARTH', 2, 800, 800, '这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，这张卡在墓地存在，除「地脚螺丝刺猬」外的「废品战士」或者有那个卡名记述的怪兽在自己场上存在的场合才能发动。这张卡守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(42431843, 'Ancient Brain', '魔天老', '魔天老', 'Normal Monster', 'Fiend', 'DARK', 3, 1000, 700, '被天界放逐的堕天使，在暗域中的战斗很出色。'),
(78665705, 'Ancient Chant', '古之咒文', '古の呪文', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的卡组·墓地选1只「太阳神之翼神龙」加入手卡，这个回合自己在通常召唤外加上只有1次，自己主要阶段可以上级召唤。 ②：把墓地的这张卡除外才能发动。发动后，这个回合中自己对「太阳神之翼神龙」的上级召唤成功的场合，那个原本的攻击力·守备力变成因为那次上级召唤而解放的怪兽的原本的攻击力·守备力各自合计数值。'),
(34487429, 'Ancient City - Rainbow Ruins', '虹之古代都市', '虹の古代都市－レインボー・ルイン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：得到自己的魔法与陷阱区域的「宝玉兽」卡数量的以下效果。 ●1张以上：这张卡不会被效果破坏。 ●2张以上：1回合1次，可以把对自己的战斗伤害变成一半。 ●3张以上：魔法·陷阱卡的发动时，把自己场上1只表侧表示的「宝玉兽」怪兽送去墓地才能发动。那个发动无效并破坏。 ●4张以上：1回合1次，可以发动。自己抽1张。 ●5张：1回合1次，以自己的魔法与陷阱区域1张「宝玉兽」卡为对象才能发动。那张卡特殊召唤。'),
(50781944, 'Ancient Crimson Ape', '古代深红猿', 'エンシェント・クリムゾン・エイプ', 'Effect Monster', 'Beast', 'LIGHT', 7, 2600, 1800, '自己场上存在的怪兽被破坏送去墓地时，自己回复1000基本分。'),
(38520918, 'Ancient Dragon', '古之龙', 'エンシェント・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1400, 1300, '①：这张卡直接攻击给与对方战斗伤害时才能发动。这张卡的等级上升1星，攻击力上升500。'),
(93221206, 'Ancient Elf', '古代精灵', 'エンシェント・エルフ', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 1450, 1200, '活了数千年的妖精，能够操纵精灵发动攻击。'),
(25862681, 'Ancient Fairy Dragon', '上古精灵龙', 'エンシェント・フェアリー・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 7, 2100, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只4星以下的怪兽特殊召唤。这个效果发动的回合，自己不能进行战斗阶段。 ②：自己主要阶段才能发动。场地区域的卡全部破坏，自己回复1000基本分。那之后，可以把和破坏的卡卡名不同的1张场地魔法卡从卡组加入手卡。');